const BY_SKU = new Map<string, ApparelCatalogEntry>(APPAREL_CATALOG.map((e) => [e.sku, e]));
const BY_SHOP: Record<ApparelShopKey, ApparelCatalogEntry[]> = {
  suzuran: APPAREL_CATALOG.filter((e) => e.shop === 'suzuran'),
  lumiere: APPAREL_CATALOG.filter((e) => e.shop === 'lumiere'),
  velours: APPAREL_CATALOG.filter((e) => e.shop === 'velours'),
};

export function apparelBySku(sku: string): ApparelCatalogEntry | undefined {
  return BY_SKU.get(sku);
}

export function shopApparelBySku(placeId: string, sku: string): ApparelCatalogEntry | undefined {
  const key = APPAREL_SHOP_PLACES[placeId];
  if (!key) return undefined;
  const hit = BY_SKU.get(sku);
  return hit && hit.shop === key ? hit : undefined;
}

function preferredSeasonsForMonth(month: number, shop?: ApparelShopKey): readonly string[] {
  if (month >= 3 && month <= 5) return shop === 'lumiere' ? ['spring', 'autumn', 'party'] : ['spring', 'autumn'];
  if (month >= 6 && month <= 8) return shop === 'lumiere' ? ['summer', 'swimwear', 'party'] : ['summer', 'swimwear', 'spring'];
  if (month >= 9 && month <= 11) return ['autumn', 'winter', 'party'];
  return ['winter', 'autumn', 'party'];
}

function dateSeed(dateStr: string, salt: string): number {
  const s = `${dateStr}:${salt}`;
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

/**
 * 按灯都世界日（YYYY-MM-DD）确定性选出当期橱窗（默认 6 款），严守 get_my_view <= 4 KB 上下文预算，
 * 同时随日期推进覆盖全量 1,407 套服饰资产。
 */
export function apparelWindowForPlace(placeId: string, dateStr = '2026-11-18', count = 6): ApparelCatalogEntry[] {
  const key = APPAREL_SHOP_PLACES[placeId];
  if (!key) return [];
  const pool = BY_SHOP[key];
  if (pool.length <= count) return [...pool];
  const month = Number(dateStr.slice(5, 7)) || 11;
  const seasons = preferredSeasonsForMonth(month, key);
  const seasonal = key === 'velours' ? pool : pool.filter((e) => seasons.includes(e.cat));
  const activePool = seasonal.length >= count ? seasonal : pool;
  const start = dateSeed(dateStr, key) % activePool.length;
  const out: ApparelCatalogEntry[] = [];
  const step = 7;
  for (let i = 0; out.length < count && i < activePool.length * 2; i++) {
    const cand = activePool[(start + i * step) % activePool.length]!;
    if (!out.some((x) => x.sku === cand.sku)) out.push(cand);
  }
  return out;
}
